import com.holdmyspot.codexunleashed.scheduler.WindowsProcess;
import java.lang.foreign.MemorySegment;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
/**
 * Verifies explicit unsupported-platform rejection without a native fallback.
 */
public final class UnsupportedCheck
{
    /**
     * Calls the real operation with otherwise-valid Linux launch inputs.
     * @param arguments explicit existing fixture directory
     * @throws Exception if unsupported acquisition appears successful or hides its category
     */
    public static void main(String[] arguments) throws Exception
    {
        var module=WindowsProcess.class.getModule();
        if(module.isNamed()==false)throw new AssertionError("Owner was not loaded from a named module");
        System.out.println("module="+module.getName());
        System.out.println("module-source="+module.getLayer().configuration().findModule(module.getName()).orElseThrow().reference().location().orElseThrow());
        Path executable=Path.of(System.getProperty("java.home"),"bin","java");
        try
        {
            WindowsProcess.start(List.of(executable.toString(),"-version"),Path.of(arguments[0]),
                Map.of(),MemorySegment.ofAddress(1));
            throw new AssertionError("Unsupported platform incorrectly launched");
        }
        catch(UnsupportedOperationException expected)
        {
            if(expected.getMessage().contains("64-bit Windows")==false)throw expected;
            System.out.println("UNSUPPORTED_PLATFORM_EXPLICIT="+expected.getMessage());
        }
        if(new WindowsProcess.Result(4294967295L,false).rootExit()!=4294967295L)
            throw new AssertionError("Unsigned result boundary changed");
        try
        {
            new WindowsProcess.Result(4294967296L,false);
            throw new AssertionError("Out-of-range root status accepted");
        }
        catch(IllegalArgumentException expected)
        {
            System.out.println("UNSIGNED_RESULT_RANGE_PASSED");
        }
    }
}

